import { lazy } from "react";
import { RoleChecker } from "../../features/auth/components/RoleChecker";

const AdminModules = lazy(() => import("../../pages/AdminModules"));
const EditQuestions = lazy(() => import("../../pages/EditQuestions"));
const Home = lazy(() => import("../../pages/Home"));
const Login = lazy(() => import("../../pages/Login"));
const Quizz = lazy(() => import("../../pages/Quizz"));
const UserManagement = lazy(() => import("../../pages/UserManagement/UserManagement"));
const Profile = lazy(() => import("../../pages/Profile"));
const Support = lazy(() => import("../../pages/Support"));
// MagicLinkVerification is a named export, so we need to map it to default
const MagicLinkVerification = lazy(() => import("../../features/auth/components/MagicLinkVerification").then(module => ({ default: module.MagicLinkVerification })));

interface RouteType {
  path: string;
  component: any;
  name: string;
  protected: boolean;
}

const routes: RouteType[] = [
  {
    path: "/",
    component: Home,
    name: "Home",
    protected: false,
  },
  // {
  //   path: "/pspo",
  //   component: Home,
  //   name: "Home",
  //   protected: false,
  // },
  {
    path: "/quizz",
    component: Quizz,
    name: "Quizz",
    protected: false,
  },
  {
    path: "/admin",
    component: () => (
      <RoleChecker allowedRoles={['admin', 'dev']}>
        <EditQuestions />
      </RoleChecker>
    ),
    name: "EditQuestions",
    protected: true,
  },
  {
    path: "/admin/modules",
    component: () => (
      <RoleChecker allowedRoles={['admin', 'dev']}>
        <AdminModules />
      </RoleChecker>
    ),
    name: "AdminModules",
    protected: true,
  },
  {
    path: "/dev/users",
    component: () => (
      <RoleChecker allowedRoles={['dev']}>
        <UserManagement />
      </RoleChecker>
    ),
    name: "UserManagement",
    protected: true,
  },
  {
    path: "/login",
    component: Login,
    name: "Login",
    protected: false,
  },
  {
    path: "/auth/verify",
    component: MagicLinkVerification,
    name: "MagicLinkVerification",
    protected: false,
  },
  {
    path: "/profile",
    component: Profile,
    name: "Profile",
    protected: true,
  },
  {
    path: "/support",
    component: Support,
    name: "Support",
    protected: true,
  },
];

export default routes;
